'use strict';
const C=WGCore,STORAGE='wordgrove.v2',LEGACY='wordgrove.v1';
const catalog=globalThis.WG_CATALOG?.words||[];
const $=s=>document.querySelector(s);
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const catNames={all:'全部分類',ceec:'官方 6000 字',gsat:'學測常考單字',custom:'個人單字'};
let state=C.empty(),storageWarning='',page='overview',category='ceec',level='all',status='all',query='',listPage=0,review=null,quiz=null,reveal=false,bookDate=C.dateKey(Date.now()),editorId=null,toastTimer,exerciseScope='all';
const PAGE_SIZE=40;
try{
  const stored=localStorage.getItem(STORAGE);
  if(stored){const parsed=JSON.parse(stored);if(!C.validState(parsed))throw Error('新版進度格式無法辨識');state={...parsed,settings:{dailyGoal:10,...parsed.settings}};}
  else{const old=localStorage.getItem(LEGACY);if(old){C.importLegacy(state,JSON.parse(old),catalog);}}
}catch(e){storageWarning='無法讀取已存進度；原資料未被更動。請先匯出原備份或還原有效備份。';}
const words=()=>C.allWords(catalog,state);
const currentWords=()=>words().filter(w=>category==='all'||w.categories.includes(category));
const findWord=id=>words().find(w=>w.id===id);
const pOf=(w,s)=>C.getProgress(state,w.id,s.id);
const when=due=>{const t=due-Date.now();if(!Number.isFinite(due))return '尚未學習';if(t<=0)return '現在可複習';if(t<3600000)return `${Math.ceil(t/60000)} 分鐘後`;if(t<C.DAY)return `${Math.ceil(t/3600000)} 小時後`;return `${Math.ceil(t/C.DAY)} 天後`;};
const daysLabel=d=>d<1?`${Math.round(d*1440)} 分鐘`:`${d} 天`;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function save(){
  // A failed/corrupt read must never silently overwrite recoverable old progress.
  if(storageWarning){toast('目前處於資料保護模式，請先匯出目前資料，再匯入有效備份。');return false;}
  try{localStorage.setItem(STORAGE,JSON.stringify(state));$('.local-label').innerHTML='<span class="status-dot"></span> 進度保存在這個瀏覽器';return true;}
  catch(e){$('.local-label').textContent='儲存空間不足，請匯出備份';toast('無法儲存進度，請立即匯出備份。');return false;}
}
function stats(){const all=words(),ws=all.map(w=>C.wordState(state,w)),today=state.logs.filter(l=>C.dateKey(l.time)===C.dateKey(Date.now()));const activeDays=new Set(state.logs.map(l=>C.dateKey(l.time)));let d=new Date(),streak=0;if(!activeDays.has(C.dateKey(d)))d.setDate(d.getDate()-1);while(activeDays.has(C.dateKey(d))){streak++;d.setDate(d.getDate()-1);}return {all,learned:ws.filter(w=>w.learned).length,mastered:ws.filter(w=>w.mastered).length,due:ws.filter(w=>w.due).length,today,streak};}
function badges(w){return w.categories.map(c=>`<span class="badge ${c==='gsat'?'mastered':''}">${esc(catNames[c]||c)}</span>`).join(' ');}
function head(eyebrow,title,sub,extra=''){return `<div class="heading"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p class="subtitle">${sub}</p></div>${extra}</div>`;}
function statCards(){const s=stats();return `<div class="stats">${[['單字庫總數',s.all.length,'跨分類重複字只計一次'],['已學習單字',s.learned,'至少完成一個義項的回想'],['已熟記單字',s.mastered,'所有收錄義項皆達 21 天間隔'],['連續學習',s.streak,'依每日完成的回想與填空計算']].map(([t,n,note])=>`<div class="stat"><div class="stat-head">${t}<span>♧</span></div><div class="stat-value">${n}<small>${t==='連續學習'?'天':'個'}</small></div><div class="stat-note">${note}</div></div>`).join('')}</div>`;}
function categorySelect(id='category'){return `<select id="${id}" aria-label="字庫分類">${Object.entries(catNames).map(([v,t])=>`<option value="${v}" ${category===v?'selected':''}>${t}</option>`).join('')}</select>`;}
function route(next){page=next;document.querySelectorAll('.page').forEach(e=>e.classList.toggle('active',e.id===page));document.querySelectorAll('nav [data-page]').forEach(e=>e.classList.toggle('active',e.dataset.page===page));$('#breadcrumb').textContent='你的學習空間 / '+({overview:'學習總覽',review:'今日複習',library:'我的單字庫',cloze:'例句填空',notebooks:'每日單字本',progress:'學習足跡'}[page]||'學習總覽');render();}
function render(){const s=stats();$('#navDue').textContent=s.due;$('#todayDate').textContent=new Date().toLocaleDateString('zh-TW',{month:'long',day:'numeric',weekday:'short'});({overview:renderOverview,library:renderLibrary,review:renderReview,cloze:renderCloze,notebooks:renderNotebooks,progress:renderProgress}[page]||renderOverview)();}
function renderOverview(){
  const s=stats(),official=catalog.filter(w=>w.categories.includes('ceec')).length,frequent=catalog.filter(w=>w.categories.includes('gsat')).length,meta=globalThis.WG_CATALOG?.meta||{};
  $('#overview').innerHTML=head('A LITTLE EVERY DAY','讓每個意思，都留下記憶。','從字義到句子，用自己的節奏建立單字森林。')+`<div class="hero"><div><span class="eyebrow">YOUR DAILY PRACTICE</span><h2>${s.due?`${s.due} 個單字，等你再次想起。`:'字庫已就緒，從今天開始。'}</h2><p>每個義項獨立安排複習；今天學過的單字會自動收進每日單字本。</p><div class="button-row"><button class="primary" data-action="go" data-go="review">開始今日學習 ↗</button><button class="secondary" data-action="go" data-go="cloze">練習英文填空</button></div></div><div class="hero-seal">Aa<small>ONE WORD<br>MANY MEANINGS</small></div></div>${statCards()}<div class="dashboard-grid"><div class="panel"><div class="panel-head"><h2>兩個分類，同一份學習進度</h2></div><button class="collection-card" data-action="collection" data-cat="ceec"><span class="collection-icon">▤</span><div><strong>官方 6000 字</strong><p>大考中心六級參考字表 · ${official.toLocaleString()} 詞條</p></div><span>↗</span></button><button class="collection-card" data-action="collection" data-cat="gsat"><span class="collection-icon">✦</span><div><strong>學測常考單字</strong><p>111–115 學年度重複出現 · ${frequent} 詞條</p></div><span>↗</span></button><p class="import-info">同一單字可同時屬於兩類；每個意思的例句與複習紀錄共用。</p></div><div class="panel"><div class="panel-head"><h2>今天的單字本</h2><button class="text-btn" data-action="go" data-go="notebooks">查看單字本 ↗</button></div>${todayBookHTML()}<div class="coverage-note">已收錄 ${Number(meta.senseCount||0).toLocaleString()} 個學習義項、${Number(meta.exampleCount||0).toLocaleString()} 個例句。${meta.incompleteSenses?`仍有 ${meta.incompleteSenses} 個義項未滿兩例句，詳見字庫說明。`:'每個收錄義項皆有至少兩個例句。'}</div></div></div><div class="panel small-panel"><details><summary>關於字庫與「常考」的依據</summary><p class="progress-info">官方字表共 6,008 詞條，不是每個字都必考。常考分類是近五年正式試卷中至少兩年出現的第 3–6 級單字，包含題幹、選項及文章；不是正確答案次數排名。中文與例句來自開放字典及補寫內容，優先收錄學習常用義，不代表涵蓋所有專業與古語義。<button class="text-btn" data-action="sources">查看來源與授權 ↗</button></p></details></div>`;
}
function todayBookHTML(){const b=C.notebooks(state,words()).find(b=>b.date===C.dateKey(Date.now()));return b?`<div class="book-today"><strong>${b.newIds.length}</strong><span>個新認識的單字</span><p>另外複習 ${b.reviewIds.length} 個單字 · 完成 ${b.practices} 次練習</p></div>`:'<div class="empty">今天的單字本，等你寫下第一筆。<br><small>完成回想評分或填空後會自動建立。</small></div>';}
function filteredWords(){return currentWords().filter(w=>(level==='all'||String(w.level)===level)&&(!query||C.norm([w.word,...w.senses.map(s=>s.zh)].join(' ')).includes(C.norm(query)))&&(()=>{const p=C.wordState(state,w);return status==='all'||status==='new'&&!p.learned||status==='learning'&&p.learned&&!p.mastered||status==='mastered'&&p.mastered||status==='due'&&p.due;})());}
function rowsHTML(list){return list.map(w=>{const p=C.wordState(state,w);return `<tr><td><button class="word-link" data-action="detail" data-id="${esc(w.id)}">${esc(w.word)}</button><div class="word-brief">${esc(w.senses.slice(0,2).map(s=>s.zh).join('；'))}</div></td><td>${badges(w)}<small class="level-label">${w.level?'L'+w.level:'自訂'} · ${w.senses.length} 個義項</small></td><td><span class="badge ${p.mastered?'mastered':''}">${p.mastered?'已熟記':p.learned?'記憶養成中':'尚未學習'}</span><small class="level-label">已學 ${p.sensesLearned}/${w.senses.length} 義 · ${when(p.next)}</small></td><td><button class="text-btn" data-action="detail" data-id="${esc(w.id)}">字義與例句 ↗</button></td></tr>`;}).join('');}
function renderLibrary(){const list=filteredWords(),pages=Math.max(1,Math.ceil(list.length/PAGE_SIZE));listPage=Math.min(listPage,pages-1);$('#library').innerHTML=head('YOUR GROWING COLLECTION','我的單字庫','依分類、級別及學習狀態整理；點選單字查看不同意思與例句。','<button class="primary" data-action="add">＋ 新增單字</button>')+`<div class="toolbar">${categorySelect()}<input type="search" id="search" aria-label="搜尋英文或中文" placeholder="搜尋英文單字或中文意思…" value="${esc(query)}"><select id="levelFilter" aria-label="級別">${[['all','所有級別'],...Array.from({length:6},(_,i)=>[String(i+1),`第 ${i+1} 級`])].map(([v,t])=>`<option value="${v}" ${level===v?'selected':''}>${t}</option>`).join('')}</select><select id="statusFilter" aria-label="學習狀態">${[['all','所有狀態'],['new','尚未學習'],['learning','記憶養成中'],['mastered','已熟記'],['due','待複習']].map(([v,t])=>`<option value="${v}" ${status===v?'selected':''}>${t}</option>`).join('')}</select></div><div class="button-row library-actions"><button class="secondary" data-action="export">匯出學習備份</button><button class="secondary" data-action="import">合併學習備份</button>${state.hidden.length?'<button class="text-btn" data-action="restore-hidden">還原隱藏單字</button>':''}</div><div class="panel"><div class="panel-head"><h2>${esc(catNames[category])}</h2><span class="today-number">${list.length.toLocaleString()} 個詞條</span></div><div class="table-wrap"><table><thead><tr><th>單字 / 常用義</th><th>分類與義項</th><th>學習情況</th><th>查看</th></tr></thead><tbody>${rowsHTML(list.slice(listPage*PAGE_SIZE,(listPage+1)*PAGE_SIZE))}</tbody></table>${list.length?'':'<div class="empty">沒有符合的單字，換個條件試試。</div>'}</div><div class="pagination"><button class="secondary" data-action="prev-page" ${listPage===0?'disabled':''}>← 上一頁</button><span>第 ${listPage+1} / ${pages} 頁</span><button class="secondary" data-action="next-page" ${listPage>=pages-1?'disabled':''}>下一頁 →</button></div></div><p class="import-info">字庫已自動匯入。學習備份會合併進度，保留現有紀錄；原始字庫 JSON 不等同學習備份。</p>`;
}
function openDetail(id){const w=findWord(id);if(!w)return;const p=C.wordState(state,w);$('#detailContent').innerHTML=`<div class="dialog-head"><div><span class="eyebrow">ONE WORD, MANY MEANINGS</span><h2 class="detail-word">${esc(w.word)}</h2><div>${badges(w)} <span class="muted">${w.senses.length} 個學習義項</span></div></div><button class="icon-btn" data-action="close-detail" aria-label="關閉字義">×</button></div><div class="button-row detail-actions"><button class="secondary" data-action="review-word" data-id="${esc(w.id)}">練習所有義項</button><button class="secondary" data-action="cloze-word" data-id="${esc(w.id)}">例句填空</button><button class="text-btn" data-action="edit" data-id="${esc(w.id)}">編輯字義與例句</button><button class="text-btn" data-action="hide" data-id="${esc(w.id)}">隱藏單字</button></div>${w.exam?`<p class="import-info">學測出現年度：${w.exam.years.join('、')}；全卷原字形共 ${w.exam.total} 次，包含選項。</p>`:''}<div class="sense-list">${w.senses.map((s,i)=>{const p=pOf(w,s);return `<section class="sense-block"><div class="sense-top"><span class="sense-number">${i+1}</span><div><span class="sense-pos">${esc(s.pos)}${s.term!==w.word?' · '+esc(s.term):''}</span><h3>${esc(s.zh)}</h3></div><span class="badge">${p.stage<0?'尚未學習':when(p.due)}</span></div>${s.explanation?`<p class="sense-explanation">${esc(s.explanation)}</p>`:''}<ol class="example-list">${s.examples.map(e=>`<li><p lang="en">${esc(e.en)}</p>${e.zh?`<small>${esc(e.zh)}</small>`:''}</li>`).join('')}</ol>${s.examples.length<2?'<p class="content-warning">此個人義項尚未滿兩個例句，可從編輯補齊。</p>':''}<small class="source-note">${esc(s.source||'個人新增')} ${s.sourceUrl?`· <a href="${esc(s.sourceUrl)}" target="_blank" rel="noopener">來源 ↗</a>`:''}</small></section>`;}).join('')}</div>${w.personalNotes?.length?`<details><summary>保留的舊版個人筆記</summary>${w.personalNotes.map(n=>`<p>${esc(n.meaning)}<br><span lang="en">${esc(n.example)}</span></p>`).join('')}</details>`:''}`;$('#detailDialog').showModal();}
function renderReview(){
 if(review){renderReviewSession();return;}
 const scoped=currentWords(),due=C.dueUnits(state,scoped),newUnits=C.newUnits(state,scoped,state.settings.dailyGoal||10),newWords=new Set(newUnits.map(u=>u.word.id)).size;
 $('#review').innerHTML=head('TIME TO RECALL','每個意思，都值得回想。','不同義項分開複習，記得其中一個意思不會替其他意思自動升級。')+`<div class="toolbar">${categorySelect()}<label class="inline-label">每次新字上限 <input type="number" id="dailyGoal" min="1" max="50" value="${state.settings.dailyGoal||10}"></label></div><div class="review-layout"><div class="panel review-plan"><div class="plan-icon">♧</div><h2>${esc(catNames[category])}</h2><p class="progress-info">目前有 <strong>${due.length}</strong> 個到期義項。<br>本次可認識 <strong>${newWords}</strong> 個單字，共 <strong>${newUnits.length}</strong> 個尚未學習的義項。</p><div class="button-row center"><button class="primary" data-action="start-due" ${due.length?'':'disabled'}>複習到期義項</button><button class="secondary" data-action="start-new" ${newUnits.length?'':'disabled'}>學習新義項</button></div></div><p class="hint">先回想再看答案，依實際熟悉程度選擇評分。所有完成的練習都會記錄到今天的單字本。</p></div>`;
}
function startReview(units){if(!units.length){toast('目前沒有符合的義項。');return;}review={units,index:0,counts:{again:0,hard:0,good:0,easy:0}};reveal=false;closeDialogs();route('review');}
function renderReviewSession(){const r=review;if(r.index>=r.units.length){$('#review').innerHTML=head('YOUR DAILY PRACTICE','這次的回想完成了。','完成的單字已自動收進今天的單字本。')+`<div class="review-layout"><div class="flashcard"><div class="summary-check">✓</div><h2 class="summary-title">完成 ${r.units.length} 個義項</h2><p class="prompt">其中 ${r.counts.good+r.counts.easy} 次記得答案。<br>忘記的義項會在 10 分鐘後再次到期。</p><div class="button-row center"><button class="primary" data-action="review-finish">回到學習總覽 →</button><button class="secondary" data-action="go" data-go="notebooks">查看今日單字本</button></div></div></div>`;return;}
const {word:w,sense:s}=r.units[r.index],p=pOf(w,s);$('#review').innerHTML=head('ONE MEANING AT A TIME','把意思，放回記憶裡。',`${esc(catNames[category])} · 每個義項獨立安排複習`,'<button class="text-btn" data-action="end-review">結束這次練習 ×</button>')+`<div class="review-layout"><div class="session-top"><span>${p.stage<0?'認識新義項':'間隔複習'} · ${esc(s.pos)}</span><span>${r.index+1} / ${r.units.length}</span></div><div class="progress-track"><div class="progress-fill" style="width:${r.index/r.units.length*100}%"></div></div><div class="flashcard"><span class="eyebrow">${esc(w.word)}</span><h2 lang="en">${esc(s.term||w.word)}</h2><button class="speak" data-action="speak" data-word="${esc(s.term||w.word)}" aria-label="播放英文發音">♪</button>${reveal?`<p class="meaning">${esc(s.zh)}</p><div class="review-examples">${s.examples.map(e=>`<p lang="en">${esc(e.en)}${e.zh?`<small>${esc(e.zh)}</small>`:''}</p>`).join('')}</div>`:`<p class="prompt">這個單字作為 ${esc(s.pos||'這個詞性')} 時，你能想起哪些意思？<br>揭開答案後，針對本次顯示的意思評分。</p>`}</div><div class="review-actions">${reveal?`<div class="ratings">${[['again','忘記了'],['hard','有點模糊'],['good','記得'],['easy','很熟悉']].map(([rating,t])=>`<button data-action="rate" data-rating="${rating}">${t}<small>${daysLabel(C.schedule(p,rating).days)}後複習</small></button>`).join('')}</div>`:'<button class="primary" data-action="reveal">顯示字義與例句 ↵</button>'}</div><p class="hint">同一個單字可能有其他意思；可從單字庫查看所有收錄義項。</p></div>`;}
function rateCurrent(rating){if(!review||!reveal)return;const u=review.units[review.index];C.rate(state,u.word,u.sense,rating);review.counts[rating]++;review.index++;reveal=false;save();render();}
let clozeCache={key:'',pool:[]};
function exerciseWords(){return currentWords().filter(w=>exerciseScope==='all'||exerciseScope==='learned'&&C.wordState(state,w).learned||exerciseScope==='due'&&C.wordState(state,w).due);}
function getPool(){const list=exerciseWords(),key=[category,exerciseScope,list.map(w=>w.id+':'+w.senses.map(s=>s.examples.map(e=>e.en).join('|')).join(';')).join(',')].join('/');if(clozeCache.key!==key)clozeCache={key,pool:C.questions(list)};return clozeCache.pool;}
function startQuiz(pool){if(!pool.length){toast('這個範圍目前沒有可填空的例句，請換個範圍。');return;}const copy=[...pool];for(let i=copy.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[copy[i],copy[j]]=[copy[j],copy[i]];}quiz={items:copy.slice(0,10),index:0,correct:0,answered:false,hinted:false,lastAnswer:'',wasCorrect:false,answerKind:''};closeDialogs();route('cloze');}
function renderCloze(){if(quiz){renderQuiz();return;}const pool=getPool();$('#cloze').innerHTML=head('FROM MEANING TO SENTENCE','例句填空，寫出英文。','根據中文義項與句子，填入符合文法的英文單字或字形。')+`<div class="toolbar">${categorySelect()}<select id="exerciseScope" aria-label="填空範圍">${[['all','全部單字'],['learned','已學習單字'],['due','到期單字']].map(([v,t])=>`<option value="${v}" ${exerciseScope===v?'selected':''}>${t}</option>`).join('')}</select></div><div class="review-layout"><div class="panel review-plan"><div class="plan-icon">Aa</div><h2>${esc(catNames[category])}</h2><p class="progress-info">目前有 ${pool.length.toLocaleString()} 個可用例句。<br>每次隨機練習最多 10 題，答錯的義項會安排短期複習。</p><button class="primary" data-action="start-quiz" ${pool.length?'':'disabled'}>開始英文填空 →</button></div><p class="hint">忽略英文字母大小寫及頭尾空白；詞尾變化須符合原句。使用首字母提示會記錄為「有點模糊」。</p></div>`;}
function renderQuiz(){const q=quiz;if(q.index>=q.items.length){$('#cloze').innerHTML=head('PRACTICE MAKES MEMORY','填空練習完成了。','完成的單字已記錄到今日單字本。')+`<div class="review-layout"><div class="flashcard"><div class="summary-check">✓</div><h2 class="summary-title">答對 ${q.correct} / ${q.items.length} 題</h2><p class="prompt">答錯的義項已安排 10 分鐘後複習。</p><div class="button-row center"><button class="primary" data-action="quiz-finish">再選擇練習範圍</button><button class="secondary" data-action="go" data-go="notebooks">查看今日單字本</button></div></div></div>`;return;}
const item=q.items[q.index];$('#cloze').innerHTML=head('RECALL THE WORD','讓句子，喚醒你的記憶。','依原句填入英文；同一單字可能使用不同字形。','<button class="text-btn" data-action="end-quiz">結束填空 ×</button>')+`<div class="review-layout"><div class="session-top"><span>英文例句填空</span><span>${q.index+1} / ${q.items.length}</span></div><div class="progress-track"><div class="progress-fill" style="width:${q.index/q.items.length*100}%"></div></div><div class="panel quiz-card"><span class="sense-pos">${esc(item.sense.pos)}</span><h2>${esc(item.sense.zh)}</h2><p class="cloze-sentence" lang="en">${esc(item.text)}</p><form id="answerForm"><label for="answerInput">填入英文 <small class="muted">（請注意單複數、時態等字形）</small></label><input type="text" id="answerInput" autocomplete="off" autocapitalize="none" spellcheck="false" placeholder="你的答案…" value="${esc(q.lastAnswer)}" ${q.answered?'disabled':''}><div class="button-row"><button class="primary" type="submit" ${q.answered?'disabled':''}>檢查答案</button><button type="button" class="text-btn" data-action="quiz-hint" ${q.answered?'disabled':''}>首字母提示</button><button type="button" class="text-btn" data-action="quiz-reveal" ${q.answered?'disabled':''}>我忘記了</button></div></form>${q.hinted&&!q.answered?`<p class="hint">提示：${esc(item.answer[0])}…</p>`:''}${q.answered?`<div class="answer-feedback ${q.wasCorrect?'correct':'incorrect'}" role="status" aria-live="polite"><strong>${q.wasCorrect?'答對了！':q.answerKind==='verb-form'?'單字選對了，請注意時態或動詞變化！':'再記一次，下一次會更熟悉。'}</strong>${q.answerKind==='verb-form'?`<p>你填的是 <span lang="en">${esc(q.lastAnswer)}</span>；本題依原句需用 <span lang="en">${esc(item.answer)}</span>。請留意時態、主詞與動詞一致，以及分詞形式。</p>`:''}<p>正確答案：<span lang="en">${esc(item.answer)}</span></p><p lang="en">${esc(item.original)}</p>${item.translation?`<small>${esc(item.translation)}</small>`:''}</div><button class="primary" data-action="quiz-next">${q.index===q.items.length-1?'查看結果':'下一題'} →</button>`:''}</div></div>`;
if(!q.answered)$('#answerInput').focus();}
function checkAnswer(forceWrong=false){if(!quiz||quiz.answered||quiz.index>=quiz.items.length)return;const item=quiz.items[quiz.index],input=$('#answerInput').value;if(!forceWrong&&!input.trim()){toast('請先填入英文，或選擇「我忘記了」。');return;}quiz.lastAnswer=input;const result=forceWrong?{correct:false,kind:'revealed'}:C.evaluateCloze(item,input);quiz.wasCorrect=result.correct;quiz.answerKind=result.kind;quiz.answered=true;if(quiz.wasCorrect)quiz.correct++;C.rate(state,item.word,item.sense,quiz.wasCorrect?(quiz.hinted?'hard':'good'):'again','cloze');save();render();}
function renderNotebooks(){const all=words(),books=C.notebooks(state,all),b=books.find(b=>b.date===bookDate),today=C.dateKey(Date.now());$('#notebooks').innerHTML=head('YOUR DAILY WORD JOURNAL','每天的單字，都有自己的頁面。','首次完成練習的單字歸入當日新字；之後再次練習記在當日複習字，不會重複算成新字。')+`<div class="notebook-layout"><div class="panel notebook-dates"><label>選擇學習日期<input type="date" id="bookDate" value="${bookDate}" max="${today}"></label>${books.slice(0,90).map(x=>`<button class="book-date ${x.date===bookDate?'selected':''}" data-action="book-date" data-date="${x.date}"><strong>${x.date}</strong><span>新字 ${x.newIds.length} · 複習 ${x.reviewIds.length}</span></button>`).join('')||'<p class="import-info">完成一次練習後，這裡就會出現第一本單字本。</p>'}</div><div class="panel"><div class="panel-head"><h2>${bookDate} 單字本</h2><span class="today-number">${b?.practices||0} 次練習</span></div>${b?`<div class="book-summary"><span>新字 <strong>${b.newIds.length}</strong></span><span>複習 <strong>${b.reviewIds.length}</strong></span><span>填空 <strong>${b.cloze}</strong></span></div><div class="button-row"><button class="secondary" data-action="review-book" data-kind="new" ${b.newIds.length?'':'disabled'}>複習本日新字</button><button class="secondary" data-action="cloze-book" ${b.newIds.length+b.reviewIds.length?'':'disabled'}>單字本例句填空</button><button class="text-btn" data-action="export-book">匯出本日單字表</button></div><h3 class="book-section-title">本日新認識</h3>${bookRows(b.newIds,all)}<h3 class="book-section-title">本日再次複習</h3>${bookRows(b.reviewIds,all)}`:'<div class="empty">這一天還沒有學習紀錄。<br>完成回想評分或例句填空，就會自動建立單字本。</div>'}</div></div>`;}
function bookRows(ids,all){const by=C.lookup(all).byId;return ids.map(id=>by.get(id)).filter(Boolean).map(w=>`<button class="book-word" data-action="detail" data-id="${esc(w.id)}"><span lang="en">${esc(w.word)}</span><small>${esc(w.senses[0].zh)}</small><span>↗</span></button>`).join('')||'<p class="import-info">沒有此類單字。</p>';}
function renderProgress(){const s=stats(),books=C.notebooks(state,words()),recent=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-(6-i));const date=C.dateKey(d),b=books.find(b=>b.date===date);return{date,label:i===6?'今天':date.slice(5),n:b?.practices||0};}),max=Math.max(1,...recent.map(d=>d.n));$('#progress').innerHTML=head('WATCH YOUR MEMORY GROW','每個意思的進步，都看得見。','字庫分類共用進度；熟記一個單字需要完成它的所有收錄義項。')+statCards()+`<div class="dashboard-grid"><div class="panel"><div class="panel-head"><h2>最近 7 天練習次數</h2><span class="today-number">累計 ${state.logs.length} 次</span></div><div class="schedule">${recent.map(d=>`<div class="day-column"><small>${d.n}</small><div class="bar" style="height:${d.n/max*135}px"></div><span>${d.label}</span></div>`).join('')}</div><p class="import-info">包含回想評分與填空，每次第一次作答記一次。</p></div><div class="panel"><div class="panel-head"><h2>義項的記憶養成</h2></div><div class="book-today"><strong>${Object.values(state.progress).filter(p=>p.stage>=0).length}</strong><span>個已學習義項</span><p>${Object.values(state.progress).filter(p=>p.stage>=4).length} 個義項已達熟記間隔。</p></div><p class="progress-info">忘記：10 分鐘後；模糊：30 分鐘或 1 天。記得則延長到 1、3、7、21、60 天；很熟悉可多前進一階。每個義項皆獨立記錄。</p></div></div><div class="panel small-panel"><p class="progress-info">單字量代表你在這個字庫的學習情況，並非完整英語詞彙量測驗。舊版進度只移到單字的第一個義項，其餘意思仍待學習；舊版個人例句保留在單字詳情的個人筆記中。</p><div class="button-row"><button class="secondary" data-action="export">匯出完整學習備份</button><button class="secondary" data-action="import">合併學習備份</button></div></div>`;}
function senseFields(s={},i=0){return `<fieldset class="sense-editor" data-sid="${esc(s.id||'')}"><legend>意思 ${i+1}</legend><label>這個意思的英文單字／字形<input class="edit-term" maxlength="180" value="${esc(s.term||'')}" placeholder="留空時使用上方的單字"></label><div class="editor-row"><label>詞性<input class="edit-pos" maxlength="60" value="${esc(s.pos||'')}" placeholder="例如 n. / v."></label><label>中文意思<input class="edit-zh" required maxlength="2000" value="${esc(s.zh||'')}" placeholder="每個不同意思分開填寫"></label></div><label>英文例句 1<textarea class="edit-example1" required maxlength="4000">${esc(s.examples?.[0]?.en||'')}</textarea></label><label>英文例句 2<textarea class="edit-example2" required maxlength="4000">${esc(s.examples?.[1]?.en||'')}</textarea></label><button type="button" class="text-btn" data-action="remove-sense">移除此意思</button></fieldset>`;}
function openEditor(id=null){editorId=id;const w=id?findWord(id):null;$('#wordForm').reset();$('#formError').textContent='';$('#wordInput').value=w?.word||'';$('#senseFields').innerHTML=(w?.senses||[{}]).map(senseFields).join('');$('#wordDialog').showModal();}
function saveEditor(e){e.preventDefault();const word=$('#wordInput').value.trim();if(!word)return;const old=editorId?findWord(editorId):null;const duplicate=words().find(w=>C.norm(w.word)===C.norm(word)&&w.id!==editorId);if(duplicate){$('#formError').textContent='這個單字已存在，請從它的詳情編輯其他義項。';return;}const fields=[...document.querySelectorAll('.sense-editor')];if(!fields.length){$('#formError').textContent='至少需要一個意思及兩個例句。';return;}const senses=[];for(const f of fields){const term=f.querySelector('.edit-term').value.trim()||word,zh=f.querySelector('.edit-zh').value.trim(),a=f.querySelector('.edit-example1').value.trim(),b=f.querySelector('.edit-example2').value.trim(),id=f.dataset.sid||crypto.randomUUID();if(!zh||!a||!b||C.norm(a)===C.norm(b)){$('#formError').textContent='每個意思都需要中文釋義與兩個不同的英文例句。';return;}const prev=old?.senses.find(s=>s.id===id);senses.push({...prev,id,term,pos:f.querySelector('.edit-pos').value.trim(),zh,examples:[{en:a,zh:prev?.examples[0]?.en===a?prev.examples[0].zh:'',source:'個人編輯'},{en:b,zh:prev?.examples[1]?.en===b?prev.examples[1].zh:'',source:'個人編輯'},...(prev?.examples.slice(2)||[])],source:'個人編輯'});}
if(old){state.overrides[old.id]={...(state.overrides[old.id]||{}),word,senses};}else{state.customWords.unshift({id:crypto.randomUUID(),word,forms:[word],categories:['custom'],senses});}save();$('#wordDialog').close();render();toast('已儲存單字的字義與例句');}
function download(name,text,type='application/json'){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function exportBackup(){download(`wordgrove-${C.dateKey(Date.now())}.json`,JSON.stringify({...state,exportedAt:new Date().toISOString(),catalogVersion:globalThis.WG_CATALOG?.meta?.version},null,2));toast('已匯出所有義項進度與每日學習紀錄');}
function exportBook(){const b=C.notebooks(state,words()).find(b=>b.date===bookDate);if(!b)return;const ids=[...b.newIds,...b.reviewIds],list=ids.map(findWord).filter(Boolean);download(`wordgrove-${bookDate}-單字本.txt`,`${bookDate} 單字本\n新字 ${b.newIds.length} / 複習 ${b.reviewIds.length}\n義項與例句來源：Open Dictionary v2.0、Wiktionary 貢獻者、Wordgrove 補寫；CC BY-SA 4.0。\nhttps://github.com/ahpxex/open-dictionary/releases/tag/v2.0\nhttps://creativecommons.org/licenses/by-sa/4.0/\n\n`+list.map(w=>`${w.word}\n`+w.senses.map((s,i)=>` ${i+1}. ${s.pos} ${s.zh}\n`+s.examples.map(e=>`    ${e.en}`).join('\n')).join('\n')).join('\n\n'),'text/plain;charset=utf-8');}
function closeDialogs(){for(const d of document.querySelectorAll('dialog'))if(d.open)d.close();}
function showSources(){const meta=globalThis.WG_CATALOG?.meta||{};$('#detailContent').innerHTML=`<div class="dialog-head"><h2>字庫來源與授權</h2><button class="icon-btn" data-action="close-detail" aria-label="關閉來源">×</button></div><pre class="source-document">${esc(meta.sourceNotice||'完整來源說明位於專案 data/CONTENT-SOURCES.md。')}</pre>`;$('#detailDialog').showModal();}
function speak(word){if(!('speechSynthesis'in window)){toast('瀏覽器不支援語音播放。');return;}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(word);u.lang='en-US';u.rate=.85;u.onerror=()=>toast('目前無法播放語音。');speechSynthesis.speak(u);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=b.dataset.id;
 if(a==='go'){closeDialogs();route(b.dataset.go);}
 if(a==='collection'){category=b.dataset.cat;query='';level='all';status='all';listPage=0;route('library');}
 if(a==='detail')openDetail(id);
 if(a==='sources')showSources();
 if(a==='close-detail')$('#detailDialog').close();
 if(a==='add')openEditor();
 if(a==='edit'){$('#detailDialog').close();openEditor(id);}
 if(a==='add-sense')$('#senseFields').insertAdjacentHTML('beforeend',senseFields({},document.querySelectorAll('.sense-editor').length));
 if(a==='remove-sense')b.closest('.sense-editor').remove();
 if(a==='hide'){state.hidden=[...new Set([...state.hidden,id])];save();closeDialogs();render();toast('已隱藏；可從單字庫還原。');}
 if(a==='restore-hidden'){state.hidden=[];save();render();}
 if(a==='prev-page'){listPage--;renderLibrary();}
 if(a==='next-page'){listPage++;renderLibrary();}
 if(a==='start-due')startReview(C.dueUnits(state,currentWords()));
 if(a==='start-new')startReview(C.newUnits(state,currentWords(),state.settings.dailyGoal||10));
 if(a==='review-word'){const w=findWord(id);if(w)startReview(w.senses.map(s=>({word:w,sense:s})));}
 if(a==='cloze-word'){const w=findWord(id);if(w)startQuiz(C.questions([w]));}
 if(a==='reveal'){reveal=true;renderReviewSession();}
 if(a==='rate')rateCurrent(b.dataset.rating);
 if(a==='end-review'||a==='review-finish'){review=null;route(a==='review-finish'?'overview':'review');}
 if(a==='start-quiz')startQuiz(getPool());
 if(a==='quiz-hint'){quiz.hinted=true;quiz.lastAnswer=$('#answerInput').value;renderQuiz();}
 if(a==='quiz-reveal')checkAnswer(true);
 if(a==='quiz-next'){quiz.index++;quiz.answered=false;quiz.hinted=false;quiz.lastAnswer='';quiz.answerKind='';render();}
 if(a==='end-quiz'||a==='quiz-finish'){quiz=null;route('cloze');}
 if(a==='book-date'){bookDate=b.dataset.date;renderNotebooks();}
 if(a==='review-book'||a==='cloze-book'){const book=C.notebooks(state,words()).find(x=>x.date===bookDate);if(book){const ids=a==='review-book'?book.newIds:[...book.newIds,...book.reviewIds],ws=ids.map(findWord).filter(Boolean);a==='review-book'?startReview(ws.flatMap(w=>w.senses.map(s=>({word:w,sense:s})))):startQuiz(C.questions(ws));}}
 if(a==='export')exportBackup();if(a==='import')$('#importFile').click();if(a==='export-book')exportBook();if(a==='speak')speak(b.dataset.word);
});
document.addEventListener('change',e=>{if(e.target.id==='category'){category=e.target.value;listPage=0;render();}if(e.target.id==='levelFilter'){level=e.target.value;listPage=0;renderLibrary();}if(e.target.id==='statusFilter'){status=e.target.value;listPage=0;renderLibrary();}if(e.target.id==='dailyGoal'){state.settings.dailyGoal=Math.max(1,Math.min(50,Math.floor(Number(e.target.value)||10)));save();renderReview();}if(e.target.id==='exerciseScope'){exerciseScope=e.target.value;renderCloze();}if(e.target.id==='bookDate'){bookDate=e.target.value||C.dateKey(Date.now());renderNotebooks();}});
function updateSearch(e){if(e.target.id!=='search'||e.isComposing)return;query=e.target.value;listPage=0;const pos=e.target.selectionStart;renderLibrary();$('#search').focus();try{$('#search').setSelectionRange(pos,pos);}catch(err){}}
document.addEventListener('input',updateSearch);document.addEventListener('compositionend',updateSearch);
document.addEventListener('submit',e=>{if(e.target.id==='answerForm'){e.preventDefault();checkAnswer();}if(e.target.id==='wordForm')saveEditor(e);});
$('#closeDialog').onclick=()=>$('#wordDialog').close();$('#exportSide').onclick=exportBackup;
$('#importFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>100*1024*1024)throw Error('備份檔案超過 100MB');const incoming=JSON.parse(await file.text());const proposed=JSON.parse(JSON.stringify(state));C.mergeBackup(proposed,incoming,catalog);if(!C.validState(proposed))throw Error('合併後的備份格式不正確');state=proposed;storageWarning='';save();review=null;quiz=null;render();toast('已合併單字與學習紀錄，原有進度已保留。');}catch(err){toast(err.message||'無法讀取備份');}e.target.value='';};
document.querySelectorAll('nav [data-page]').forEach(b=>b.onclick=()=>route(b.dataset.page));$('.brand').onclick=e=>{e.preventDefault();route('overview');};
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&page==='review'&&review&&!reveal&&!document.querySelector('dialog[open]')&&!['INPUT','TEXTAREA','BUTTON'].includes(document.activeElement.tagName)){e.preventDefault();reveal=true;renderReviewSession();}});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&!document.querySelector('dialog[open]'))render();});
if(!catalog.length){$('#overview').innerHTML='<div class="empty">字庫未載入，請確認 catalog.js 與網頁在同一個資料夾，再重新開啟。</div>';}else{render();if(storageWarning)toast(storageWarning);else save();}
